from collections import Counter
import json
import math
from pathlib import Path
import sys

import numpy as np

WORK = Path(__file__).resolve().parent
BLOCKS, WIDTH, REPS, DRAWS = 24, 48, 48, 99
WINDOW, EXCESS = 3, 5
MODES = ("compress", "barrier")
RULES = ("fixed", "reselect", "include_ties")
SCENARIOS = (
    "exchangeable_unique", "exchangeable_tie", "exchangeable_all_tied",
    "tiered_inventories", "piecewise_independent", "reversible_persistence",
    "cipher_noise_02", "cipher_noise_08",
)
LAYOUTS = {
    "whole": [slice(0, WIDTH)],
    "aligned": [slice(i, i + 12) for i in range(0, WIDTH, 12)],
    "shifted": [slice(i, min(i + 12, WIDTH)) for i in range(6, WIDTH, 12)] + [slice(0, 6)],
}


def shuffled(book, layout, rng):
    result = book.copy()
    for positions in LAYOUTS[layout]:
        result[:, positions] = rng.permuted(book[:, positions], axis=1)
    return result


def named_counts(counts):
    return np.repeat(np.arange(len(counts), dtype=np.int32), counts)


def source_book(scenario, seed):
    rng = np.random.default_rng(seed)
    if scenario in SCENARIOS[:3]:
        if scenario == "exchangeable_all_tied":
            counts = [48] * 24
        else:
            counts = [160, 121 if scenario == "exchangeable_unique" else 160]
            quotient, remainder = divmod(BLOCKS * WIDTH - sum(counts), 22)
            counts += [quotient + (i < remainder) for i in range(22)]
        return rng.permutation(named_counts(counts)).reshape(BLOCKS, WIDTH)
    if scenario == "tiered_inventories":
        book = []
        for block in range(BLOCKS):
            common = [0] * 8 + [1] * 8 + [2, 3, 4, 5] * 2
            private = [6 + 4 * (block // 6) + i for i in range(4)] * 6
            # Keep exactly two dominant globally tied types.
            book.append(rng.permutation(common + private)[:WIDTH])
        return np.asarray(book, dtype=np.int32)
    if scenario == "piecewise_independent":
        parts = []
        for block in range(BLOCKS):
            phase = block % 4
            schedule = [0, 1, 2, 3] if phase in (0, 1, 2) else [1, 2, 3, 0]
            parts.append(np.concatenate([
                rng.permutation([0, 1] + [2 + 5 * stage + i for i in range(5)] * 2)
                for stage in schedule
            ]))
        return np.asarray(parts, dtype=np.int32)
    if scenario == "reversible_persistence":
        fresh = rng.integers(0, 24, size=(BLOCKS, WIDTH), dtype=np.int32)
        retain = rng.random(size=fresh.shape) < 0.60
        for pos in range(1, WIDTH):
            fresh[:, pos] = np.where(retain[:, pos], fresh[:, pos - 1], fresh[:, pos])
        return fresh
    book = rng.integers(0, 24, size=(BLOCKS, WIDTH), dtype=np.int32)
    continue_cycle = rng.random(size=book.shape) < 0.84
    for pos in range(1, WIDTH):
        book[:, pos] = np.where(continue_cycle[:, pos], (book[:, pos - 1] + 1) % 24, book[:, pos])
    cipher = rng.permutation(24)
    noise = rng.random(book.shape) < (0.02 if scenario == "cipher_noise_02" else 0.08)
    encoded = cipher[book]
    encoded[noise] = rng.integers(0, 24, size=int(noise.sum()))
    assert np.array_equal(np.argsort(cipher)[encoded[~noise]], book[~noise])
    return encoded.astype(np.int32)


def stop_mask(book, n_types, stops, mode):
    omit = np.zeros(n_types, dtype=bool)
    omit[stops] = True
    mask = omit[book]
    if mode == "compress":
        # Sort only the omission flags, keeping the original order of every retained word.
        order = np.argsort(mask, axis=1, kind="stable")
        book = np.take_along_axis(book, order, axis=1)
        mask = np.arange(book.shape[1])[None, :] >= (~mask).sum(axis=1)[:, None]
    return book, mask


def pair_counts(book, n_types, stops, mode):
    words, mask = stop_mask(book, n_types, stops, mode)
    codes, signs = [], []
    for lag in range(1, WINDOW + 1):
        left, right = words[:, :-lag], words[:, lag:]
        valid = left != right
        for position in range(lag + 1):
            valid &= ~mask[:, position:position + left.shape[1]]
        a, b = left[valid], right[valid]
        codes.append(np.minimum(a, b) * n_types + np.maximum(a, b))
        signs.append(np.where(a < b, 1, -1))
    distinct, index = np.unique(np.concatenate(codes), return_inverse=True)
    difference = np.bincount(index, weights=np.concatenate(signs))
    return int(np.count_nonzero(np.abs(difference) > EXCESS)), len(distinct)


def top_first(book, top_flags):
    flat = book.ravel()
    return int(flat[np.argmax(top_flags[flat])])


def evaluate(book, layout, seed):
    n_types = int(book.max()) + 1
    totals = np.bincount(book.ravel(), minlength=n_types)
    is_top = totals == max(totals)
    top = np.flatnonzero(is_top)
    first = top_first(book, is_top)
    observed = [[pair_counts(book, n_types, [first], mode),
                 pair_counts(book, n_types, top, mode)] for mode in MODES]
    counters = np.zeros((len(MODES), len(RULES)), dtype=int)
    supported = np.array([[bool(one[1]), bool(one[1]), bool(all_[1])] for one, all_ in observed])
    rng = np.random.default_rng(seed)
    reselection = 0
    for _ in range(DRAWS):
        null = shuffled(book, layout, rng)
        chosen = top_first(null, is_top)
        reselection += chosen != first
        for i, mode in enumerate(MODES):
            fix = pair_counts(null, n_types, [first], mode)
            resel = fix if chosen == first else pair_counts(null, n_types, [chosen], mode)
            full = fix if len(top) == 1 else pair_counts(null, n_types, top, mode)
            for j, (n, d) in enumerate((fix, resel, full)):
                obs_n, obs_d = observed[i][j == 2]
                supported[i, j] &= d > 0
                counters[i, j] += n * obs_d >= obs_n * d
    p = {
        mode: {rule: (1 + int(counters[i, j])) / (1 + DRAWS) if supported[i, j] else None
               for j, rule in enumerate(RULES)}
        for i, mode in enumerate(MODES)
    }
    return {"tops": len(top), "observed": observed, "reselected_different": reselection, "p": p}


def wilson(k, n):
    if not n:
        return None
    z = 1.959963984540054
    fraction = k / n
    center = (fraction + z * z / (2 * n)) / (1 + z * z / n)
    radius = z * math.sqrt(fraction * (1 - fraction) / n + z * z / (4 * n * n)) / (1 + z * z / n)
    return [max(0, center - radius), min(1, center + radius)]


def summary(books, independent=True):
    results = {}
    for mode in MODES:
        changed = sum(b["p"][mode]["fixed"] != b["p"][mode]["reselect"] for b in books)
        entry = {"changed_p": changed,
                 "reject_decision_changed": sum(
                     (b["p"][mode]["fixed"] is not None and b["p"][mode]["fixed"] <= .05)
                     != (b["p"][mode]["reselect"] is not None and b["p"][mode]["reselect"] <= .05)
                     for b in books)}
        for rule in RULES:
            valid = [b["p"][mode][rule] for b in books if b["p"][mode][rule] is not None]
            reject = sum(p <= .05 for p in valid)
            entry[rule] = {"valid": len(valid), "reject": reject,
                           "wilson_95": wilson(reject, len(valid)) if independent else None}
        results[mode] = entry
    return {"top_count_histogram": dict(Counter(b["tops"] for b in books)), "modes": results}


def synthetic(samples):
    data = {}
    for i, scenario in enumerate(SCENARIOS):
        layouts = LAYOUTS if scenario == "piecewise_independent" else ["whole"]
        cases = [(270001 + i * 10000 + j * 2, source_book(scenario, 270001 + i * 10000 + j * 2))
                 for j in range(samples)]
        for layout in layouts:
            books = [dict(seed=seed, **evaluate(book, layout, seed + 1)) for seed, book in cases]
            data[f"{scenario}:{layout}"] = {"books": books, "summary": summary(books)}
            print(scenario, layout, summary(books)["top_count_histogram"],
                  [[summary(books)["modes"][m][r]["reject"] for r in RULES] for m in MODES], flush=True)
        seed, book = cases[0]
        rename = np.random.default_rng(seed + 700).permutation(int(book.max()) + 1)
        assert evaluate(book, "whole", seed + 1) == evaluate(rename[book], "whole", seed + 1)
    return data


def historical(filename, known_negative):
    data = []
    for i, book in enumerate(json.loads((WORK / filename).read_text())):
        words = sorted({w for block in book["blocks"] for w in block})
        vocabulary = {w: n for n, w in enumerate(words)}
        encoded = np.array([[vocabulary[w] for w in block] for block in book["blocks"]], dtype=np.int32)
        assert encoded.shape == (BLOCKS, WIDTH)
        seed = 490001 + 100 * i
        originals = evaluate(encoded, "whole", seed)
        rng = np.random.default_rng(seed + 1)
        negatives = [evaluate(shuffled(encoded, "whole", rng), "whole", seed + j + 2)
                     for j in range(known_negative)]
        data.append({k: v for k, v in book.items() if k != "blocks"} |
                    {"original": originals, "conditional_negatives": negatives,
                     "conditional_summary": summary(negatives, independent=False)})
    return data


def main():
    smoke = "--smoke" in sys.argv
    result = {
        "synthetic": synthetic(2 if smoke else REPS),
        "historical": historical("historical.json", 1 if smoke else 4),
        "historical_capped": historical("historical-frequency-capped.json", 1 if smoke else 4),
        "numpy": np.__version__,
    }
    (WORK / ("smoke.json" if smoke else "results.json")).write_text(
        json.dumps(result, separators=(",", ":")) + "\n"
    )


if __name__ == "__main__":
    main()

