from collections import Counter
import numpy as np
from calibrate import SCENARIOS, MODES, LAYOUTS, pair_counts, shuffled, source_book

def scalar(book, stops, mode):
    counts = Counter()
    for row in book.tolist():
        if mode == "compress":
            row = [x for x in row if x not in stops]
        for i, x in enumerate(row):
            if x in stops:
                continue
            for y in row[i + 1:i + 4]:
                if y in stops:
                    break
                if x != y:
                    counts[x, y] += 1
    pairs = {tuple(sorted((a, b))) for a, b in counts}
    return sum(abs(counts[a, b] - counts[b, a]) > 5 for a, b in pairs), len(pairs)

checks = 0
for scenario_index, scenario in enumerate(SCENARIOS):
    for replicate in range(3):
        seed = 8121 + 100 * scenario_index + replicate
        rng = np.random.default_rng(seed)
        book = source_book(scenario, seed)
        counts = np.bincount(book.ravel())
        tops = np.flatnonzero(counts == counts.max())
        for layout in LAYOUTS:
            random = shuffled(book, layout, rng)
            for slc in LAYOUTS[layout]:
                assert np.array_equal(np.sort(random[:, slc]), np.sort(book[:, slc]))
            for mode in MODES:
                for stop in (tops[:1], tops, np.arange(len(counts))):
                    assert pair_counts(random, len(counts), stop, mode) == scalar(random, stop, mode)
                    checks += 1
print(f"{checks} exact pair-count matches with separate scalar implementation; each stratum preserved")

