"""Exact conditional directional-pair permutation tests for a finite block orbit."""

import itertools
import json
import math
import random
import sys
from collections import Counter
from functools import cache
from pathlib import Path

import numpy as np


PAIRS = list(itertools.combinations(range(4), 2))
PAIR_INDEX = {pair: i for i, pair in enumerate(PAIRS)}
COMMON_DENOMINATOR = math.lcm(*range(1, len(PAIRS) + 1))
ALPHA = {"0.025": (1, 40), "0.05": (1, 20), "0.1": (1, 10)}


@cache
def block_orders(block):
    """Distinct orders are equiweighted because values repeat within each multiset."""
    counts = Counter(block)
    keys = sorted(counts)
    def unique_orders(prefix):
        if len(prefix) == len(block):
            yield prefix
            return
        for value in keys:
            if counts[value]:
                counts[value] -= 1
                yield from unique_orders(prefix + (value,))
                counts[value] += 1
    return np.array(list(unique_orders(())), dtype=np.int8)


@cache
def block_components(block, removed, mode, window):
    orders = block_orders(block)
    components = np.zeros((len(orders), len(PAIRS), 2), dtype=np.int16)
    for row, order in enumerate(orders.tolist()):
        if mode == "compress":
            order = [item for item in order if item not in removed]
        else:
            order = [None if item in removed else item for item in order]
        for i, first in enumerate(order):
            if first is None:
                continue
            for second in order[i + 1 : i + 1 + window]:
                if second is None:
                    break
                if first == second:
                    continue
                lo, hi = sorted((first, second))
                pair = PAIR_INDEX[lo, hi]
                components[row, pair, 0] += 1
                components[row, pair, 1] += 1 if first == lo else -1
    return components


def sum_components(blocks, removed, mode, window, sizes):
    total = np.zeros((math.prod(sizes), len(PAIRS), 2), dtype=np.int16)
    for index, block in enumerate(blocks):
        features = block_components(block, removed, mode, window)
        tiled = np.repeat(features, math.prod(sizes[index + 1 :]), axis=0)
        total += np.tile(tiled, (math.prod(sizes[:index]), 1, 1))
    return total


def tail_numerators(scores):
    frequencies = np.bincount(scores, minlength=COMMON_DENOMINATOR + 1)
    return np.cumsum(frequencies[::-1])[::-1]


def rating(components, excess):
    occurring = np.count_nonzero(components[:, :, 0], axis=1)
    skewed = np.count_nonzero(np.abs(components[:, :, 1]) > excess, axis=1)
    score = np.zeros(len(components), dtype=np.int16)
    positive = occurring > 0
    score[positive] = skewed[positive] * COMMON_DENOMINATOR // occurring[positive]
    return score, occurring


def summary(numerators, count, support):
    return {
        "orbit": count,
        "possible_p_numerators": sorted(set(numerators.tolist())),
        "supported": int(np.count_nonzero(support)),
        "minimum_p": int(numerators.min()) / count,
        "rejected": {alpha: int(np.count_nonzero(numerators * denominator <= numerator * count))
                     for alpha, (numerator, denominator) in ALPHA.items()},
    }


def check_orbit(blocks, window=3, excess=5, cap=75_000):
    """Calculate the p-value for every possible observation, without Monte Carlo."""
    sizes = [len(block_orders(block)) for block in blocks]
    count = math.prod(sizes)
    if count > cap:
        return None
    frequencies = Counter(itertools.chain.from_iterable(blocks))
    top = frozenset(value for value, frequency in frequencies.items()
                    if frequency == max(frequencies.values()))
    first_block = next(index for index, block in enumerate(blocks) if top.intersection(block))
    chosen = np.array([next(value for value in order if value in top)
                       for order in block_orders(blocks[first_block])], dtype=np.int8)
    chosen = np.tile(
        np.repeat(chosen, math.prod(sizes[first_block + 1 :])), math.prod(sizes[:first_block])
    )
    result = {"blocks": blocks, "per_block_orbits": sizes, "top": sorted(top), "window": window,
              "strict_excess": excess, "results": {}}
    for mode in ("compress", "barrier"):
        observed = np.zeros(count, dtype=np.int16)
        observed_support = np.zeros(count, dtype=np.int16)
        frozen_p = np.zeros(count, dtype=np.int64)
        for stop in sorted(top):
            total = sum_components(blocks, frozenset({stop}), mode, window, sizes)
            scores, support = rating(total, excess)
            selected = chosen == stop
            observed[selected] = scores[selected]
            observed_support[selected] = support[selected]
            frozen_p[selected] = tail_numerators(scores)[scores[selected]]
        reselected_p = tail_numerators(observed)[observed]
        if len(top) == 1:
            assert np.array_equal(frozen_p, reselected_p)
        inclusive, support = rating(sum_components(blocks, top, mode, window, sizes), excess)
        inclusive_p = tail_numerators(inclusive)[inclusive]
        for pvalues in (reselected_p, inclusive_p):
            hist = np.bincount(pvalues, minlength=count + 1)
            assert (np.cumsum(hist) <= np.arange(count + 1)).all()
        recorded = {
            "frozen": summary(frozen_p, count, observed_support),
            "reselected": summary(reselected_p, count, observed_support),
            "tie_inclusive": summary(inclusive_p, count, support),
            "changed_p": int(np.count_nonzero(frozen_p != reselected_p)),
        }
        more_extreme = reselected_p - frozen_p
        if more_extreme.max() > 0:
            selected = int(np.argmax(more_extreme))
            at_index = np.unravel_index(selected, sizes)
            obs = [block_orders(block)[i].tolist() for block, i in zip(blocks, at_index)]
            recorded["max_gap_example"] = {"observed_blocks": obs, "selected_stop": int(chosen[selected]),
                "fixed_numerator": int(frozen_p[selected]), "reselected_numerator": int(reselected_p[selected])}
        result["results"][mode] = recorded
    return result


FIXTURES = {
    "balanced_two_blocks": ((0, 0, 1, 1, 2, 3), (0, 1, 2, 2, 3, 3)),
    "top_tie_two_blocks": ((0, 0, 0, 1, 2), (0, 1, 1, 1, 2, 3)),
    "unequal_single_top": ((0, 0, 0, 1, 2), (0, 0, 1, 1, 2, 3)),
    "uniform_repeated_four_blocks": ((0, 1, 2, 3),) * 4,
    "top_tie_first_block_asymmetric": ((0, 0, 1, 2), (0, 1, 1, 2), (0, 1, 2, 3), (0, 1, 1, 3)),
    "designed_five_five_four": (tuple([0] * 5 + [1] * 5 + [2] * 4),),
}


def score_result(result):
    """Order candidates by strongest extent of exceeding nominal alpha, then p-value shifts."""
    high = (0.0, 0.0)
    for mode in result["results"].values():
        n = mode["frozen"]["orbit"]
        overshoot = max(value / n - float(alpha) for alpha, value in mode["frozen"]["rejected"].items())
        example = mode.get("max_gap_example", {})
        gap = (example.get("reselected_numerator", 0) - example.get("fixed_numerator", 0)) / n
        high = max(high, (overshoot, gap))
    return high


def search(seed, count):
    rng = random.Random(seed)
    retained = []
    tested = set()
    for _ in range(count):
        blocks = tuple(tuple(sorted(rng.choices(range(4), k=rng.choice((3, 4, 4, 5, 5, 6)))))
                       for _ in range(rng.choice((2, 3, 3, 4, 4, 5))))
        if blocks in tested:
            continue
        stats = Counter(itertools.chain.from_iterable(blocks))
        if len(stats) < 3 or list(stats.values()).count(max(stats.values())) < 2:
            continue
        result = check_orbit(blocks)
        if result:
            tested.add(blocks)
            retained.append((score_result(result), result))
    retained.sort(reverse=True, key=lambda row: row[0])
    return {"seed": seed, "generated": count, "tested": len(retained), "top": retained[:5],
            "overshoot_count": sum(value[0] > 1e-15 for value, _ in retained)}


def main():
    rounds = int(sys.argv[1]) if len(sys.argv) > 1 else 1_200
    results = {
        "fixed_fixtures": {name: check_orbit(blocks, cap=500_000) for name, blocks in FIXTURES.items()},
        "exploratory_search": search(164419, rounds),
    }
    Path(__file__).with_name("orbit_results.json").write_text(json.dumps(results, indent=2) + "\n")


if __name__ == "__main__":
    main()

