"""Independent combinatorial count without constructing the three-type permutations."""

from itertools import combinations
from math import comb


def extreme_counts(top_count, other_count, barrier):
    """With A/B tied, compute frozen tail and dynamically selected tail."""
    n = top_count + other_count
    total = comb(n + top_count, top_count) * comb(n, top_count)
    frozen = chosen = 0
    if barrier:
        # Inner cut gaps break adjacency; two outer gaps affect only the chosen top type.
        gap_masks = []
        for size in range(min(top_count, n - 1) + 1):
            for interior in combinations(range(1, n), size):
                variants = []
                for left in (0, 1):
                    for right in (0, 1):
                        count = size + left + right
                        if 1 <= count <= top_count:
                            first_gap = 0 if left else interior[0] if interior else n
                            variants.append((first_gap, comb(top_count - 1, count - 1)))
                if variants:
                    boundaries = (*interior, n)
                    ranges = tuple(zip((0, *interior), boundaries))
                    gap_masks.append((ranges, variants))
    for retained_positions in combinations(range(n), top_count):
        members = set(retained_positions)
        order = [int(i in members) for i in range(n)]
        first_b = retained_positions[0]
        if not barrier:
            # In a binary run, signed comparisons telescope to a boundary sum for each lag.
            imbalance = sum(sum(order[:lag]) - sum(order[-lag:]) for lag in (1, 2, 3))
            if abs(imbalance) > 5:
                frozen += comb(n + top_count, top_count)
                chosen += comb(n + top_count, top_count) - comb(n + top_count - 1 - first_b, top_count)
            continue
        run_skew = [[0] * (n + 1) for _ in range(n)]
        for start in range(n):
            for stop in range(start + 2, n + 1):
                run_skew[start][stop] = sum(
                    sum(order[start : start + lag]) - sum(order[stop - lag : stop])
                    for lag in range(1, min(3, stop - start - 1) + 1)
                )
        for ranges, variants in gap_masks:
            imbalance = sum(run_skew[start][end] for start, end in ranges)
            if abs(imbalance) > 5:
                frozen += sum(count for _, count in variants)
                chosen += sum(count for first_gap, count in variants if first_gap <= first_b)
    return frozen, chosen * 2, total


def main():
    assert extreme_counts(5, 4, False) == (12012, 15042, 252252)
    assert extreme_counts(5, 4, True) == (7896, 8360, 252252)
    for a in range(4, 9):
        for c in range(3, min(a, 7)):
            if a + c > 12:
                continue
            print(a, c, [(mode, extreme_counts(a, c, mode)) for mode in (False, True)], flush=True)


if __name__ == "__main__":
    main()
